// ============================================
// VALIDATION INPUT - MCP Documents Estimate
// RFC-014 Extraction Pattern
// ============================================

const input = $input.first().json;
const body = input.body || input;

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];

// --- OPTIONAL context fields (extract for tracing, NO validation errors) ---
const userId = body.user_id || ctx.user_id || null;
const guildId = body.guild_id || ctx.guild_id || null;
const userRequest = body.user_request || ctx.user_request || null;

// --- Required: file_url OR file_base64 ---
const fileUrl = body.file_url || ctx.file_url;
const fileBase64 = body.file_base64 || ctx.file_base64;

const hasFile = !!(fileUrl || fileBase64);
if (!hasFile) {
  errors.push('file_url or file_base64 required');
}

// --- Optional parameters with defaults ---
const fileType = body.file_type || ctx.file_type || (fileUrl?.split('.').pop()?.toLowerCase()) || 'unknown';
const action = body.action || ctx.action || 'translate';
const pluginContext = body.plugin_context || ctx.plugin_context || {};

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };
}

return {
  valid: true,
  file_url: fileUrl,
  file_base64: fileBase64,
  file_type: fileType,
  action: action,
  plugin_context: pluginContext,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  startTime: Date.now()
};

// ============================================
// BUILD VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'documents-estimate',
    mode: 'error',
    latency_ms: 0,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request
  },
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  user_id: input.user_id,
  guild_id: input.guild_id,
  user_request: input.user_request
};

// ============================================
// ESTIMATE AND CALCULATE - MCP Documents Estimate
// ============================================

const prevData = $('Validate Input').first().json;

const fileType = prevData.file_type;
const action = prevData.action;
const pluginContext = prevData.plugin_context || {};

// Pricing par defaut
const defaultPricing = {
  translate: { base: 5, per_1k_tokens: 1.0, per_page: 2, ocr_bonus: 3, max: 50 },
  summarize: { base: 3, per_1k_tokens: 0.5, per_page: 1, ocr_bonus: 3, max: 30 }
};
const pricing = pluginContext.pricing?.[action] || defaultPricing[action] || defaultPricing.translate;

// OCR thresholds configurables (Phase 2.2)
const defaultOcrThresholds = {
  min_confidence: 0.7,
  hebrew_min_confidence: 0.6,
  aramaic_min_confidence: 0.5,
  retry_on_low_confidence: true
};
const ocrThresholds = pluginContext.ocr_thresholds || defaultOcrThresholds;

// Determiner si OCR est requis
const imageTypes = ['png', 'jpg', 'jpeg', 'webp', 'gif', 'bmp', 'tiff'];
const isImage = imageTypes.includes(fileType?.toLowerCase());
const ocrRequired = isImage || fileType === 'pdf';

// Detecter langue potentielle pour ajuster seuils OCR
const detectedLanguage = pluginContext.detected_language || 'unknown';
const isHebrewContent = detectedLanguage === 'hebrew' || detectedLanguage === 'he';
const isAramaicContent = detectedLanguage === 'aramaic' || detectedLanguage === 'arc';

// Ajuster le seuil de confiance selon la langue
let minConfidenceThreshold = ocrThresholds.min_confidence;
if (isHebrewContent) {
  minConfidenceThreshold = ocrThresholds.hebrew_min_confidence;
} else if (isAramaicContent) {
  minConfidenceThreshold = ocrThresholds.aramaic_min_confidence;
}

// Estimation selon le type
let estimatedPages, estimatedTokens, ocrConfidencePreview;

if (isImage) {
  estimatedPages = 1;
  estimatedTokens = 500;
  ocrConfidencePreview = isHebrewContent ? 0.75 : (isAramaicContent ? 0.65 : 0.85);
} else if (fileType === 'pdf') {
  estimatedPages = 5;
  estimatedTokens = 2500;
  ocrConfidencePreview = isHebrewContent ? 0.80 : (isAramaicContent ? 0.70 : 0.90);
} else {
  estimatedPages = 3;
  estimatedTokens = 1500;
  ocrConfidencePreview = 1.0;
}

// Calcul des credits: base + (tokens/1000 * rate) + (pages * page_rate) + ocr_bonus
const base = pricing.base || 5;
const tokenCost = (estimatedTokens / 1000) * (pricing.per_1k_tokens || 1.0);
const pageCost = estimatedPages * (pricing.per_page || 2);
const ocrCost = ocrRequired ? (pricing.ocr_bonus || 3) : 0;

const total = base + tokenCost + pageCost + ocrCost;
const maxCredits = pricing.max || 50;
const estimatedCredits = Math.min(Math.ceil(total), maxCredits);

// Marge de securite de 10%
const tokensWithMargin = Math.ceil(estimatedTokens * 1.1);

// Warnings
const warnings = [];
if (ocrConfidencePreview < minConfidenceThreshold) {
  warnings.push(`OCR confidence (${ocrConfidencePreview}) below threshold (${minConfidenceThreshold})`);
}
if (ocrConfidencePreview < 0.8) {
  warnings.push('OCR confidence may vary on full document');
}
if (estimatedPages > 10) {
  warnings.push('Document exceeds recommended 10 pages limit');
}
if (isHebrewContent || isAramaicContent) {
  warnings.push(`${isHebrewContent ? 'Hebrew' : 'Aramaic'} content detected - using specialized OCR thresholds`);
}

const latencyMs = Date.now() - prevData.startTime;

const result = {
  estimation: {
    tokens: tokensWithMargin,
    pages: estimatedPages,
    ocr_required: ocrRequired,
    ocr_confidence_preview: ocrConfidencePreview,
    detected_language: detectedLanguage
  },
  credits: {
    estimated: estimatedCredits,
    breakdown: {
      base: base,
      tokens: Math.round(tokenCost * 100) / 100,
      pages: pageCost,
      ocr: ocrCost
    },
    max_possible: maxCredits
  },
  ocr_thresholds: {
    applied: minConfidenceThreshold,
    config: ocrThresholds
  },
  warnings: warnings
};

return {
  success: true,
  data: result,
  user_id: prevData.user_id,
  guild_id: prevData.guild_id,
  user_request: prevData.user_request,
  _trace: {
    service_response: result,
    provider: 'documents-estimate',
    mode: 'success',
    latency_ms: latencyMs,
    user_id: prevData.user_id,
    guild_id: prevData.guild_id,
    user_request: prevData.user_request
  }
};

